# Concussion and CTE. Run with _scripts/gen_sheets.py
fact("concussion",
 "Concussion: Symptoms, Red Flags, Recovery and Return to Sport",
 "Concussion explained: symptoms, red flags that need emergency care, why the first days need rest but not darkness, return to school, work and sport, and the 21-day rule.",
 "Concussion", "Concussion",
 "A concussion is a brain injury from a knock to the head or body that shakes the brain. You don’t need to be knocked out. Most adults recover within 2 weeks and most children within 4, with a step-by-step return to activity.",
 '<p class="callout"><b>Call 000 or go to an emergency department</b> for a worsening headache, repeated vomiting, a seizure, increasing drowsiness or confusion, weakness or numbness, slurred speech, neck pain, or if the person was knocked out. Same for anyone on blood thinners or over 65.</p>' +
 h2("Symptoms", [
   "Headache, “pressure in the head”, dizziness or balance problems",
   "Feeling dazed, foggy or slowed down; trouble concentrating or remembering",
   "Nausea, blurred vision, sensitivity to light or noise",
   "Tiredness, poor sleep, irritability, emotional or anxious",
   "Symptoms can appear or worsen over the first 24–48 hours"]) +
 h2("The first days", [
   "<b>Relative rest for 24–48 hours</b>: quiet activity, normal sleep, no alcohol. Total darkness and bed rest aren’t needed and can slow recovery.",
   "Someone should stay with the person for the first night if they were knocked out or have worrying symptoms.",
   "<b>Then gradually more:</b> light walking and normal daily activities help recovery, as long as symptoms don’t clearly worsen.",
   "Screens in moderation, with breaks. Paracetamol for headache."]) +
 h2("Back to school, work and sport", [
   "Return to learning and work first, with breaks and lighter loads if needed, usually within days.",
   "<b>Sport:</b> follow a graded return, step by step, only moving on if symptoms don’t come back.",
   "<b>Community and youth sport in Australia:</b> no return to contact or collision sport for at least 21 days, and only once symptom-free and cleared by a doctor.",
   "“If in doubt, sit them out.” A second knock before the brain has recovered can be more serious."]) +
 h2("If symptoms linger", [
   "A minority have symptoms beyond 4 weeks (persisting post-concussion symptoms).",
   "Treatment is targeted: graded aerobic exercise, vestibular (balance) physiotherapy, neck treatment, sleep and headache care, and help with mood or anxiety.",
   "See your GP if symptoms aren’t improving after 2 weeks, or sooner if they’re worsening."]),
 [("How long does concussion take to recover?", "Most adults recover within 2 weeks and most children within 4 weeks. A minority have symptoms for longer and benefit from targeted treatment."),
  ("When can you return to sport after concussion?", "Follow a graded return. Under Australian guidelines for community and youth sport, wait at least 21 days before returning to contact or collision sport, and only once symptom-free and cleared by a doctor."),
  ("Should you rest in a dark room after concussion?", "No. Rest quietly for 24–48 hours, then gradually increase activity. Strict rest and darkness can slow recovery.")],
 [("Concussion in Sport Australia", "https://www.concussioninsport.gov.au/", "Australian guidelines and return-to-sport plans. Free."),
  ("healthdirect 1800 022 222", "https://www.healthdirect.gov.au/concussion", "24/7 nurse advice. Free.")],
 [("Australian Concussion Guidelines for Youth and Community Sport (2024)", "https://www.concussioninsport.gov.au/"), ("Consensus statement on concussion in sport, Amsterdam 2022 (BJSM 2023)", "https://bjsm.bmj.com/content/57/11/695")],
 [("Chronic Traumatic Encephalopathy (CTE)", "/cte/"), ("Tension Headache", "/tension-headache/"), ("Dizziness and Vertigo", "/vertigo/")],
 groups=["Brain and nerves"], blurb="A brain injury from a knock that shakes the brain. Red flags, recovery, and the 21-day rule for contact sport.",
 search="concussion head injury knock mild traumatic brain injury return to sport")

fact("cte",
 "CTE (Chronic Traumatic Encephalopathy): Head Impacts and the Brain",
 "CTE explained: the brain disease linked to repeated head impacts in contact sport and the military, what is and isn’t known, symptoms, diagnosis after death, and prevention.",
 "Chronic Traumatic Encephalopathy (CTE)", "Chronic traumatic encephalopathy",
 "CTE is a brain disease linked to years of repeated head impacts, including the many smaller knocks that never cause a diagnosed concussion. It can only be confirmed after death. The best protection is fewer head impacts, especially in young people.",
 h2("What it is", [
   "A slowly progressive disease in which an abnormal protein, tau, builds up in a distinctive pattern around small blood vessels in the brain.",
   "Found in people with long exposure to repeated head impacts: contact and collision sports (American football, rugby, Australian football, boxing, ice hockey, soccer heading) and military blasts.",
   "Risk rises with the number of years of exposure. Most people with head impacts will not develop it.",
   "Major health bodies now accept that repeated head impacts can cause CTE."]) +
 h2("Possible symptoms", [
   "Problems with memory, thinking and planning",
   "Mood and behaviour changes: depression, irritability, impulsivity, aggression or explosive anger",
   "Later: dementia and movement problems in some",
   "Symptoms usually appear years to decades after the exposure ends",
   "These symptoms have many other, treatable causes, so get assessed"]) +
 h2("Diagnosis", [
   "CTE can only be confirmed by examining the brain after death.",
   "In life, doctors can diagnose “traumatic encephalopathy syndrome”, a research term for the clinical picture.",
   "Scans and blood tests that detect CTE during life are being studied.",
   "The Australian Sports Brain Bank, set up in Sydney in 2018, has found CTE in former Australian athletes."]) +
 h2("Prevention", [
   "Limit head impacts in training: less contact training and no unnecessary heading drills.",
   "Delay tackling and heading in children, and follow concussion rules strictly.",
   "Report and properly recover from every concussion."]) +
 h2("If you’re worried", [
   "See your GP about memory, mood or behaviour changes. Depression, sleep apnoea, alcohol, thyroid problems and medicines are common, treatable causes.",
   "If you’re having thoughts of self-harm, call Lifeline 13 11 14 or 000."]),
 [("Can CTE be diagnosed while you are alive?", "Not yet with certainty. It’s confirmed only by examining the brain after death, although doctors can describe a clinical syndrome and tests are being researched."),
  ("Does one concussion cause CTE?", "CTE is linked to many repeated head impacts over years, not usually a single concussion. Risk rises with the years of exposure."),
  ("What are the symptoms of CTE?", "Memory and thinking problems, depression, irritability, impulsivity and aggression, sometimes progressing to dementia. These symptoms also have other treatable causes.")],
 [("Australian Sports Brain Bank", "https://www.sydney.edu.au/medicine-health/our-research/research-centres/brain-and-mind-centre.html", "Research brain bank based in Sydney."),
  ("Lifeline 13 11 14", "https://www.lifeline.org.au/", "24/7 crisis support. Free.")],
 [("NINDS: Chronic traumatic encephalopathy", "https://www.ninds.nih.gov/health-information/disorders/chronic-traumatic-encephalopathy-cte"), ("Katz DI et al. NINDS consensus diagnostic criteria for traumatic encephalopathy syndrome (Neurology 2021)", "https://pubmed.ncbi.nlm.nih.gov/33722990/")],
 [("Concussion", "/concussion/"), ("Lowering Your Dementia Risk", "/dementia-prevention/"), ("Depression", "/depression/")],
 groups=["Brain and nerves"], blurb="A brain disease linked to years of repeated head impacts. Confirmed only after death. Prevention means fewer hits.",
 search="cte chronic traumatic encephalopathy head knocks football boxing tau")
